  async function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const requestId = ++intakeRequestRef.current; const generation = ++projectGenerationRef.current; projectIdRef.current = null; setError(null); setSubmitting(true); resetProjectState(); setProject(null); try { const known_facts = intake.known_facts.split("\n").map((fact) => fact.trim()).filter(Boolean); const created = await request<Project>("/api/v1/projects", { method: "POST", body: JSON.stringify({ name: intake.name.trim(), description: intake.description.trim() || null, geography: intake.geography.trim() || null, business_type: intake.business_type.trim() || null, budget: numberOrNull(intake.budget), deadline_days: numberOrNull(intake.deadline_days), known_facts: known_facts.length ? known_facts : null, language }) }); if (requestId !== intakeRequestRef.current) return; projectIdRef.current = created.id; setProject(created); setProjects((all) => [...all, created]); setHistory([]); setHistoryLoaded(true); const createdRun = await request<Run>(`/api/v1/projects/${created.id}/analysis-runs`, { method: "POST", body: JSON.stringify({ inputs: {} }) }); if (!isCurrentProject(projectToken(created.id, generation)) || requestId !== intakeRequestRef.current) return; setRun(createdRun); await pollRun(created.id, createdRun.id); } catch (e) { if (requestId === intakeRequestRef.current) setError(localizedRequestError(e, t.requestFailed)); } finally { if (requestId === intakeRequestRef.current) setSubmitting(false); } }
